import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";import"./chunks/assets.ByxXdwmG.js";var i=JSON.parse(`{"title":"Sign-in, accounts and invitations","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/accounts.md","filePath":"en/guides/accounts.md","lastUpdated":1794405696000}`),a={name:`en/guides/accounts.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="sign-in-accounts-and-invitations" tabindex="-1">Sign-in, accounts and invitations <a class="header-anchor" href="#sign-in-accounts-and-invitations" aria-label="Permalink to “Sign-in, accounts and invitations”">​</a></h1><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to “Sign in”">​</a></h2><p>In the admin console, enter your email address and sign in with a passkey. You verify your identity with your device&#39;s face, fingerprint or PIN, or with a supported security key. Your email address is your sign-in ID.</p><p>In a preview environment protected by Cloudflare Access, you first enter through Access with an email code or similar. This is a separate entrance from the JevSense passkey.</p><h2 id="first-time-use" tabindex="-1">First-time use <a class="header-anchor" href="#first-time-use" aria-label="Permalink to “First-time use”">​</a></h2><p><strong>The first administrator of an environment</strong> registers a passkey with a display name, an email address and the initial ADMIN_TOKEN. The first user is the superuser. In a Preview linked to Access, registration is fixed to the authenticated email, and you don&#39;t enter the shared token.</p><p><strong>If you were invited</strong>, open the link you received from an administrator and register a display name and a passkey. A link is valid for 24 hours and works once. If it has expired, ask the administrator to reissue it.</p><p>If you already have an account, sign in with that passkey and accept the invitation. You don&#39;t need to create a new account or passkey for each site.</p><h2 id="manage-your-display-name-and-passkeys" tabindex="-1">Manage your display name and passkeys <a class="header-anchor" href="#manage-your-display-name-and-passkeys" aria-label="Permalink to “Manage your display name and passkeys”">​</a></h2><p>You can change your display name from your account at the bottom left. The name is shared across all sites, and your sign-in ID and permissions don&#39;t change. Changing your email address is not included in this release.</p><p><img src="/jev-personalization/images/account.png" alt="Account settings" width="1440" height="1000"></p><p>Use &quot;Add another passkey (「別のパスキーを追加」)&quot; to register a spare device or key. You can&#39;t delete the last one. Important operations ask you to verify with your passkey within the last 5 minutes.</p><h2 id="permissions-and-switching-sites" tabindex="-1">Permissions and switching sites <a class="header-anchor" href="#permissions-and-switching-sites" aria-label="Permalink to “Permissions and switching sites”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Main scope</th></tr></thead><tbody><tr><td>Superuser</td><td>All sites, all users and environment settings</td></tr><tr><td>Site admin</td><td>Campaigns, settings, design, members and custom code for the site you belong to</td></tr><tr><td>Editor</td><td>Create, deliver and check standard campaigns for the site you belong to</td></tr><tr><td>Viewer</td><td>Read-only access to the site you belong to</td></tr></tbody></table><p>If you belong to several sites, switch between them in the header at the top. Your permission can differ from site to site. If a site doesn&#39;t appear, ask an administrator to check your membership.</p><h2 id="invite-members" tabindex="-1">Invite members <a class="header-anchor" href="#invite-members" aria-label="Permalink to “Invite members”">​</a></h2><p>A site admin opens &quot;Members (「メンバー」)&quot;, specifies an email address and a permission, and shares the invitation link with the person directly. No email is sent automatically. This also doesn&#39;t mean that ownership of the email address has been verified automatically.</p><p>Reissuing for the same email invalidates the previous link. Cancel invitations you no longer need. To change the permission of a registered member, use the member list instead of inviting again.</p><h2 id="if-you-lose-your-device" tabindex="-1">If you lose your device <a class="header-anchor" href="#if-you-lose-your-device" aria-label="Permalink to “If you lose your device”">​</a></h2><p>First try another registered passkey. If you can&#39;t, choose &quot;If you can&#39;t use a passkey (「パスキーが使えない場合」)&quot; and register a new passkey with a recovery code you saved beforehand.</p><p>There are 8 recovery codes, shown only when issued. Reissuing invalidates the old codes. When recovery completes, the old passkeys, all sign-ins and the remaining codes are invalidated too, so issue new codes.</p><p>If you don&#39;t have a code either, ask a superuser to verify your identity and issue a one-time recovery link that is valid for 5 minutes. The last active superuser can&#39;t be disabled or demoted.</p><h2 id="sign-in-expiry" tabindex="-1">Sign-in expiry <a class="header-anchor" href="#sign-in-expiry" aria-label="Permalink to “Sign-in expiry”">​</a></h2><p>You need to sign in again after 30 minutes of inactivity, or 12 hours after signing in. &quot;End all other sign-ins (「他のログインをすべて終了」)&quot; ends every sign-in except this browser. Disabling a user, changing global permissions and recovery also invalidate sessions.</p><h2 id="who-can-handle-jev-keys" tabindex="-1">Who can handle Jev keys <a class="header-anchor" href="#who-can-handle-jev-keys" aria-label="Permalink to “Who can handle Jev keys”">​</a></h2><p><a href="./jev">A site&#39;s Jev connection and usage</a> is for site admins and superusers only. Editors and viewers can&#39;t even view it. Changing a key requires identity verification within the last 5 minutes. A saved key itself is never shown again to anyone.</p>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};